package net.civeira.phylax.feature.identity.userprofile.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.userprofile.domain.UserProfile;
import net.civeira.phylax.feature.identity.userprofile.domain.valueobject.PictureUrlVO;

class PictureUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of picture url of user profile")
  void test_picture_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    PictureUrlValueHolder<Object> value = new PictureUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.pictureUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getPictureUrlValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getPictureUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.pictureUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getPictureUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getPictureUrl().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of picture url of user profile")
  void test_picture_url_value_holder_assign_value_object() {
    Object holder = new Object();
    PictureUrlValueHolder<Object> value = new PictureUrlValueHolder<>(holder);
    PictureUrlVO vo = PictureUrlVO.from("one");
    Assertions.assertFalse(value.getPictureUrlValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.pictureUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getPictureUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.pictureUrl(Optional.empty()));
    Assertions.assertFalse(value.getPictureUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.pictureUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getPictureUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of picture url of user profile against the original")
  void test_picture_url_value_holder_read() {
    Object holder = new Object();
    PictureUrlValueHolder<Object> value = new PictureUrlValueHolder<>(holder);
    PictureUrlVO vo = PictureUrlVO.from("one");
    PictureUrlVO other = PictureUrlVO.from("one");
    UserProfile original = Mockito.mock(UserProfile.class);
    Mockito.when(original.getPictureUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readPictureUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readPictureUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.pictureUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readPictureUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readPictureUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of picture url of user profile")
  void test_picture_url_value_holder_unset() {
    Object holder = new Object();
    PictureUrlValueHolder<Object> value = new PictureUrlValueHolder<>(holder);
    PictureUrlVO vo = PictureUrlVO.from("one");
    value.pictureUrl(vo);
    Assertions.assertSame(holder, value.unsetPictureUrlIfMatches("pictureUrl_other"));
    Assertions.assertTrue(value.getPictureUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetPictureUrlIfMatches("pictureUrl"));
    Assertions.assertFalse(value.getPictureUrlValue().isPresent(),
        "The field name must clear the value");
    value.pictureUrl(vo);
    Assertions.assertSame(holder, value.unsetPictureUrl());
    Assertions.assertFalse(value.getPictureUrlValue().isPresent(), "Unset must clear the value");
  }
}
